const targets = game.user.targets;

if (targets.size === 0) {
  ui.notifications.warn("Please target at least one token!");
} else {
  const damageRoll = await new Roll("4d6 + 7").evaluate();
  const reduction = damageRoll.total;


  for (let token of targets) {
    const actor = token.actor;
    const hp = actor.system.health.value ?? 0;
    const hpMax = actor.system.health.max ?? 1; 
    const currentSpirit = actor.system.spirit.value ?? 0;
    const currentRisk = actor.system.risk.value ?? 0;

    let overkillMultiplier = 1; 
    if (hp < 0) {
      overkillMultiplier += Math.floor(Math.abs(hp) / hpMax);
    }

    const totalSpiritLoss = reduction * overkillMultiplier;
    const totalRiskGain = 2 * overkillMultiplier;

    const newSpirit = Math.max(-999, currentSpirit - totalSpiritLoss);
    const newRisk = currentRisk + totalRiskGain;

    await actor.update({
      "system.health.value": hpMax,
      "system.spirit.value": newSpirit,
      "system.risk.value": newRisk
    });

    let overkillText = `<div style="color:black; font-weight:bold;">BREAK x${overkillMultiplier}!</div>`;

    let content = `
    <div class="dice-roll"><div class="dice-result">
      <div style="text-align:center; margin-bottom:4px;">${overkillText}</div>
      <div style="display: flex; flex-direction: row; gap: 4px; justify-content: space-around;">
        <div style="flex: 1; text-align: center; border: 1px solid #777; border-radius: 3px; padding: 4px;">
          <div style="font-size: 0.7em; font-weight: bold; border-bottom: 1px solid #777;">SPIRIT LOSS</div>
          <div class="dice-total" style="border:none;">${totalSpiritLoss}</div>
        </div>
        <div style="flex: 1; text-align: center; border: 1px solid #777; border-radius: 3px; padding: 4px;">
          <div style="font-size: 0.7em; font-weight: bold; border-bottom: 1px solid #777;">RISK GAIN</div>
          <div class="dice-total" style="border:none;">+${totalRiskGain}</div>
        </div>
      </div>
      <div style="margin-top:4px; font-size:11px; text-align:center;">${token.name}: Health Reset to Max</div>
    </div></div>`;

    await ChatMessage.create({
      speaker: ChatMessage.getSpeaker({ actor: actor }),
      content: content,
      rolls: [damageRoll.toJSON()]
    });

    ui.notifications.info(`${token.name} breaks x${overkillMultiplier}, losing ${totalSpiritLoss} Spirit.`);
  }
}
